   208	                        buffer[j++] = '\\';
   209	                else if (i == (str->size - 1) && str->data[i] == ' ')
   210	                        buffer[j++] = '\\';
   211	
   212	                buffer[j++] = str->data[i];
   213	        }
   214	
   215	        /* null terminate the string */
   216	        buffer[j] = 0;
   217	        escaped->data = buffer;
   218	        escaped->size = j;
   219	
   220	        return 0;
   221	      cleanup:
   222	        gnutls_free(buffer);
   223	        return ret;
   224	}
